	/** Adds a deterministic pseudo-random graph and returns the expected "subjects that are also objects" count. */
	private long addRandomGraph() {
		java.util.Random random = new java.util.Random(42);
		java.util.Set<org.eclipse.rdf4j.model.Value> subjects = new java.util.HashSet<>();
		java.util.Set<org.eclipse.rdf4j.model.Value> objects = new java.util.HashSet<>();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI[] predicates = new IRI[8];
			for (int i = 0; i < predicates.length; i++) {
				predicates[i] = vf.createIRI(EX, "p" + i);
			}
			conn.begin();
			for (int i = 0; i < 5000; i++) {
				IRI subject = vf.createIRI(EX, "n" + random.nextInt(1500));
				IRI predicate = predicates[random.nextInt(predicates.length)];
				org.eclipse.rdf4j.model.Value object;
				int kind = random.nextInt(4);
				if (kind == 0) {
					object = vf.createIRI(EX, "n" + random.nextInt(1500));
				} else if (kind == 1) {
					object = vf.createIRI(EX, "other" + random.nextInt(500));
				} else {
					object = vf.createLiteral("literal-" + random.nextInt(2000));
				}
				conn.add(subject, predicate, object);
				subjects.add(subject);
				objects.add(object);
			}
			conn.commit();
		}
		subjects.retainAll(objects);
		return subjects.size();
	}

